CREATE TABLE IF NOT EXISTS supplier_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants(id),supplier_id uuid NOT NULL REFERENCES suppliers(id),amount numeric(14,2) NOT NULL,method text NOT NULL DEFAULT 'cash',reference text,paid_by uuid REFERENCES users(id),paid_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants(id),customer_id uuid NOT NULL REFERENCES customers(id),amount numeric(14,2) NOT NULL,method text NOT NULL DEFAULT 'cash',reference text,received_by uuid REFERENCES users(id),received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants(id),supplier_id uuid NOT NULL REFERENCES suppliers(id),entry_type text NOT NULL,reference_id uuid,debit numeric(14,2) NOT NULL DEFAULT 0,credit numeric(14,2) NOT NULL DEFAULT 0,balance numeric(14,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid REFERENCES tenants(id),customer_id uuid NOT NULL REFERENCES customers(id),entry_type text NOT NULL,reference_id uuid,debit numeric(14,2) NOT NULL DEFAULT 0,credit numeric(14,2) NOT NULL DEFAULT 0,balance numeric(14,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS customer_ledger_customer_idx ON customer_ledger(customer_id,created_at); CREATE INDEX IF NOT EXISTS supplier_ledger_supplier_idx ON supplier_ledger(supplier_id,created_at);
